Поле `value` — private. Конструктор инициализирует через список. Метод `remainder()` возвращает остаток.
<pre class="code-block"><code>class IntNumber {
    int value;
public:
    IntNumber(int v) : value(v) {}
    int remainder() const { return value % 5; }
};</code></pre>

Используем манипуляторы `hex` / `uppercase` для 16-ричного вывода:
<pre class="code-block"><code>class IntNumber {
    int value;
public:
    IntNumber(int v) : value(v) {}
    void printHex() const {
        cout << "Hex: " << uppercase << hex << value << dec << endl;
    }
};</code></pre>

Приведение `char → int` даёт ASCII-код символа:
<pre class="code-block"><code>class Symbol {
    char ch;
public:
    Symbol(char c) : ch(c) {}
    void printCode() const {
        cout << "Символ '" << ch << "' имеет код: "
             << static_cast<int>(ch) << endl;
    }
};</code></pre>

Функция `sin()` из `<cmath>` принимает радианы, поэтому переводим:
<pre class="code-block"><code>#include <cmath>
const double PI = 3.14159265358979323846;

class Angle {
    double degrees;
public:
    Angle(double d) : degrees(d) {}
    double sinValue() const {
        return sin(degrees * PI / 180.0);
    }
};</code></pre>

Ключевые моменты: поля `protected` (доступ из наследника), метод `virtual` (для полиморфизма), деструктор `virtual`.
<pre class="code-block"><code>class Point2D {
protected:
    double x, y;
public:
    Point2D(double x, double y) : x(x), y(y) {}
    virtual void print() {
        cout << "x=" << x << ", y=" << y;
    }
    virtual ~Point2D() {}
};</code></pre>

Конструктор вызывает `Point2D(x, y)`. Метод `print()` сначала вызывает `Point2D::print()`, затем выводит z.
<pre class="code-block"><code>class Point3D : public Point2D {
    double z;
public:
    Point3D(double x, double y, double z)
        : Point2D(x, y), z(z) {}
    void print() override {
        Point2D::print();
        cout << ", z=" << z;
    }
};</code></pre>

Для статического полиморфизма — методы **НЕ** виртуальные:
<pre class="code-block"><code>class Square {
protected:
    double side;
public:
    Square(double s) : side(s) {}
    double area() { return side * side; }
    void print() {
        cout << "side=" << side << ", area=" << area();
    }
};</code></pre>

Объём куба = площадь основания × сторона. Вызываем `Square::area()` внутри:
<pre class="code-block"><code>class Cube : public Square {
public:
    Cube(double s) : Square(s) {}
    double volume() { return area() * side; }  // area() из Square
    void print() {
        cout << "side=" << side << ", volume=" << volume();
    }
};</code></pre>

Указатель `Square*` → вызывает `Square::print()`, даже если указывает на Cube:
<pre class="code-block"><code>int main() {
    Square sq(5.0);
    Cube cu(5.0);

    Square* p = &sq;
    p->print(); cout << endl;  // side=5, area=25

    p = &cu;
    p->print(); cout << endl;  // side=5, area=25 (НЕ volume!)
    // Статическое связывание: вызывается Square::print()

    cu.print(); cout << endl;  // side=5, volume=125
    return 0;
}</code></pre>

Объём шара V = 4/3·πr³. Можно выразить как `compute()` базового (πr²) × r × 4/3:
<pre class="code-block"><code>class Sphere : public Circle {
public:
    Sphere(double r) : Circle(r) {}
    double compute() override {
        return Circle::compute() * r * 4.0 / 3.0;
    }
    void print() override {
        cout << "r=" << r << ", volume=" << compute();
    }
};</code></pre>

Наследуем от `out_of_range`. Храним некорректные значения:
<pre class="code-block"><code>class TimeError : public out_of_range {
    int h, m, s;
public:
    TimeError(int h, int m, int s)
        : out_of_range("Invalid time"), h(h), m(m), s(s) {}
    void print() const {
        cerr << what() << ": "
             << h << ":" << m << ":" << s << endl;
    }
};</code></pre>

`lock_guard` захватывает мьютекс на время вывода строки — другой поток не сможет вклиниться:
<pre class="code-block"><code>#include <iostream>
#include <thread>
#include <mutex>
using namespace std;

mutex mtx;

void printNumbers(int n, const string& name) {
    for (int i = 1; i <= n; i++) {
        lock_guard<mutex> lock(mtx);
        cout << name << ": " << i << endl;
    }
}</code></pre>

После завершения печати — устанавливаем флаг и посылаем `notify_one()`:
<pre class="code-block"><code>void printNumbers(int n, const string& name) {
    for (int i = 1; i <= n; i++) {
        lock_guard<mutex> lock(mtx);
        cout << name << ": " << i << endl;
    }
    {
        lock_guard<mutex> lock(mtx);
        done = true;
    }
    cv.notify_one();
}</code></pre>

`cv.wait()` блокирует главный поток, пока `done` не станет `true`:
<pre class="code-block"><code>int main() {
    thread t(printNumbers, 5, "Child");

    // Главный поток ждёт оповещения
    unique_lock<mutex> lock(mtx);
    cv.wait(lock, []{ return done; });
    cout << "Main: дочерний поток завершён!" << endl;

    t.join();
    return 0;
}</code></pre>
